INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('c047405f-da3f-49e5-89dc-3063614a884e', 'radical', '青', 'blue', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Anda memiliki kehidupan di atas bulan (abaikan bahwa kehidupan tidak memiliki slide kecil di sisi kiri). Seperti apa kehidupan di bulan? Pertama-tama, mereka tidak memiliki udara, jadi mereka mungkin terlihat sangat biru karena sesak napas. Saat Anda bertemu mereka, ternyata Anda benar. Mereka adalah peradaban orang-orang biru. Bayangkan mereka semua tinggal di sana, berwarna biru dan Smurfy.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c047405f-da3f-49e5-89dc-3063614a884e', 'Biru', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('1123c6d2-df83-441c-8c70-9b3690ef4b8d', 'radical', '市', 'city', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Anda sudah mempelajari kanji 市, yang artinya kota. Kami juga memperlakukannya sebagai radikal, karena ini muncul di banyak kanji lainnya. Jika digunakan secara radikal, tetap berarti kota.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1123c6d2-df83-441c-8c70-9b3690ef4b8d', 'Kota', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('53e6fc76-9e71-4fd5-8eaa-f2489b784ad5', 'radical', '扌', 'fingers', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ini terlihat seperti tangan (手) radikal, tetapi lebih kecil. Itu karena itu hanya jari. Anda tidak selalu memiliki ruang untuk seluruh tangan untuk menulis kanji, tetapi selalu ada ruang untuk beberapa jari.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('53e6fc76-9e71-4fd5-8eaa-f2489b784ad5', 'Jari', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('63c00bc1-7621-4461-9d72-88a77ef81058', 'radical', '寺', 'temple', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Orang radikal ini terlihat seperti kuil di atas bukit, bukan? Dengan semua lapisannya, apa lagi? Bayangkan saja garis horizontal pertama sebagai dasar candi berornamen yang menyeimbangkan bukit di bawahnya dan Anda tidak akan kesulitan mengingat garis radikal ini.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('63c00bc1-7621-4461-9d72-88a77ef81058', 'Kuil', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('a7295854-9e5c-44e6-a89f-852b7ed0e5f8', 'radical', '癶', 'tent', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Saya akui, tenda ini agak aneh, tetapi tenda yang akan melindungi Anda dari benda-benda yang mencoba masuk (itulah mengapa tenda ini memiliki semua paku). Itu yang terbaik yang dapat Anda lakukan, mengingat Anda berada di dalam bangunan kain/plastik.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a7295854-9e5c-44e6-a89f-852b7ed0e5f8', 'Tenda', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('7a5f74ec-2fa8-41a1-b148-46c33bae657b', 'radical', '开', 'lantern', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Bayangkan lentera gaya lama. Letaknya di atas beberapa kaki (Anda hanya dapat melihat dua dari sudut ini) dan berada dalam dudukan berbentuk kotak di bagian atas. Anda bisa membayangkan ini berjejer di jalanan sebelum ada listrik, bukan? Itu sebabnya kaum radikal ini adalah lentera.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7a5f74ec-2fa8-41a1-b148-46c33bae657b', 'Lentera', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('d6e5ff31-7b77-41ef-91d0-646c10166db6', 'radical', '[Yurt]', 'yurt', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ada kanopi dengan meja kecil dan kursi di dalamnya. Ini adalah yurt! Awalnya mungkin terlihat seperti kanopi, tetapi saat Anda masuk ke dalamnya, terdapat banyak furnitur bagus untuk Anda bersantai.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d6e5ff31-7b77-41ef-91d0-646c10166db6', 'Yurt', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('53ac50f3-3d6e-430e-97ca-0f292ee32218', 'radical', '介', 'jammed-in', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Jenis radikal ini terlihat seperti anak panah, tapi bukan anak panah biasa. Itu melengkung dan dipaksakan, bukan? Seolah-olah ia mencoba memberi tahu Anda bahwa ada sesuatu yang tersangkut di mana pun ia menunjuk.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('53ac50f3-3d6e-430e-97ca-0f292ee32218', 'Macet', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('b3a67baf-044a-461d-aad7-159e8cf778a0', 'radical', '[Senjata]', 'gun', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ini terlihat seperti pistol panjang yang mengarah ke kanan. Anda memiliki sandaran bahu di sebelah kiri, dan laras di sebelah kanan. Bayangkan benda itu digantung dalam kotak di dinding museum.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b3a67baf-044a-461d-aad7-159e8cf778a0', 'Senjata', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('032fe3b4-282f-4096-8f43-64e13a1c65cc', 'radical', '重', 'heavy', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Radikal ini terdiri dari seribu desa. Jika Anda mencoba mengangkatnya, apakah itu? Berat! Dan mungkin gila. Tapi ingatlah betapa beratnya seribu desa.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('032fe3b4-282f-4096-8f43-64e13a1c65cc', 'Berat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('afe8cbaa-ac8a-47e3-9202-eadb65c1f5db', 'radical', '勹', 'prison', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ini terlihat seperti semacam kandang – itulah sebabnya ini adalah penjara. Ia membungkus dirinya sendiri di sekitar benda-benda dan menguncinya di sana. Penjara cukup menakutkan, bahkan sebelum Anda membayangkan penjara perlahan-lahan melayang turun dari langit untuk menjebak Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('afe8cbaa-ac8a-47e3-9202-eadb65c1f5db', 'Penjara', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('c7954769-6c83-4a71-926c-16e5174ea1df', 'radical', '品', 'products', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Tiga kotak ditumpuk di atas satu sama lain. Ini adalah produk yang menunggu untuk dikirim.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c7954769-6c83-4a71-926c-16e5174ea1df', 'Produk', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('7d28f16a-ffde-4134-a39f-3d10b0d77a98', 'radical', '尸', 'flag', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Lihat bendera radikal ini? Ada sebuah tiang dengan bendera di ujungnya, tertiup angin. Pada dasarnya, radikal ini terlihat seperti sebuah bendera.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7d28f16a-ffde-4134-a39f-3d10b0d77a98', 'Bendera', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('5c84d8fd-049a-475a-815c-fe81e071db07', 'radical', '几', 'table', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Apa yang terjadi jika Anda meletakkan permukaan datar di atas sepasang kaki? Anda mendapatkan meja.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5c84d8fd-049a-475a-815c-fe81e071db07', 'Tabel', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('e5137206-140c-4345-a13c-989ef04067b2', 'radical', '虫', 'insect', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ada sesuatu yang pribadi di mulutmu. Anda merahasiakannya karena Anda tidak ingin orang lain menghakimi Anda. Mengapa? Karena itu serangga. Anda suka makan serangga, tetapi masyarakat sepertinya menganggapnya salah. Jangan khawatir, teman. Suatu hari nanti seluruh dunia akan menerima makan serangga seperti Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e5137206-140c-4345-a13c-989ef04067b2', 'Serangga', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('f3e8d3a4-4a35-45a9-aa97-114af91de63b', 'radical', '廴', 'yoga', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ini terlihat seperti seseorang yang mengambil langkah besar dan meregangkan tubuhnya. Apakah itu terdengar seperti sesuatu yang Anda tahu? Seharusnya begitu, karena itulah yang Anda lakukan dalam yoga. Regangkan kaki dan lengan Anda sampai Anda terlihat radikal. Besar! Anda sedang melakukan yoga sekarang!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f3e8d3a4-4a35-45a9-aa97-114af91de63b', 'Yoga', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('30114c45-609d-48a6-8961-08d312d08e0b', 'radical', '石', 'stone', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ada daun yang tumbuh dari benda persegi (biasanya berupa mulut, tapi kali ini tidak). Daun itu tumbuh dari batu. Maksudku, tentu saja, karena daun tidak tumbuh dari mulut. Saya harap. Bayangkan sebuah batu di tengah alam dengan daun yang tumbuh di atasnya atau tepat di belakangnya dan Anda tidak akan pernah melupakan hal radikal ini!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('30114c45-609d-48a6-8961-08d312d08e0b', 'Batu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('3abdc14a-225d-4baf-9b70-51585fba0d11', 'radical', '[Musim semi]', 'spring', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Radikal ini terlihat seperti tanaman baru yang tumbuh ke atas dan keluar dari tanah. Itu karena ini adalah musim semi yang radikal. Musim semi adalah musim (dan musim radikal) yang penuh dengan kehidupan baru yang terus berkembang!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3abdc14a-225d-4baf-9b70-51585fba0d11', 'Musim semi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('4057fb17-8cb5-4db0-a63f-6a03f27c9eda', 'radical', '[Topi]', 'hat', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Tahukah kamu topi sawah itu? Yang bentuknya radikal begini? Itu sebabnya radikal ini adalah topi.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4057fb17-8cb5-4db0-a63f-6a03f27c9eda', 'Topi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('28f8f1cb-dd32-47a3-9717-48c8303e91ee', 'radical', 'ホ', 'angel', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Pertama, ada tanda silang di tengah, yang otomatis menjadikan ini radikal berbasis agama. Salib itu adalah kerangka tubuh seseorang dan yang keluar darinya adalah sayap. Ini adalah malaikat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('28f8f1cb-dd32-47a3-9717-48c8303e91ee', 'Malaikat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('7eaaf6bc-578d-4b8f-9bf5-8374a9bb9e02', 'radical', '羊', 'sheep', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ini adalah seekor domba dan Anda melihatnya dari atas. Lihat kedua telinga dan tubuh domba menghadap ke belakang (dengan seluruh bulunya menyembul ke samping) dan kemudian ekor kecil mencuat ke belakang. Domba yang lucu!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7eaaf6bc-578d-4b8f-9bf5-8374a9bb9e02', 'Domba', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('546020c2-1aff-4896-8a67-d2ee2e191df3', 'radical', '尺', 'shrimp', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Radikal ini memiliki kepala kecil dan beberapa kaki udang yang mencuat keluar. Itu karena itu udang!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('546020c2-1aff-4896-8a67-d2ee2e191df3', 'Udang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('e1e1b536-8c96-4450-b319-1ea1d685561a', 'radical', '豕', 'pig', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Anda sudah mengetahui adanya unsur radikal dalam hal ini, itu seharusnya menjadi petunjuk. Hewan apa itu? Letaknya di dalam tanah, tertutup lumpur. Juga, ada jari-jari kakinya yang tergeletak di sana-sini, karena hewan ini akan memakan apa saja (cara yang baik untuk menyingkirkan mayat... kudengar). Lalu hewan apa yang berlumuran lumpur dan memakan jari kaki karena mau memakan apa saja? Itu babi!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e1e1b536-8c96-4450-b319-1ea1d685561a', 'Babi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('5a266cd1-fd58-4cf0-bc14-aa168899c508', 'kanji', '青', '青', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Radikal biru dan kanji biru sama persis.', 'Kamu merasa sangat sedih. Terutama karena kulit, rambut, dan mata Anda semuanya membiru. Shougun (しょう) mengetahuinya dan sekarang dia kembali. Dia meletakkan tangannya di bahumu dan kemudian menunjuk pedangmu (せい). Warnanya biru juga! Anda tidak sendirian!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5a266cd1-fd58-4cf0-bc14-aa168899c508', 'Biru', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5a266cd1-fd58-4cf0-bc14-aa168899c508', 'せい', 'onyomi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5a266cd1-fd58-4cf0-bc14-aa168899c508', 'しょう', 'onyomi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5a266cd1-fd58-4cf0-bc14-aa168899c508', 'あお', 'kunyomi', false) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('784e2a30-6fa1-4bbb-b719-9f381b929111', 'kanji', '姉', '姉', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Satu-satunya wanita di kota ini adalah kakak perempuanmu. Dia satu-satunya wanita yang dikelilingi oleh sekelompok pria, tapi dia mengejar mimpinya di kota besar.', 'Kakak perempuanmu mungkin telah pindah ke kota, tapi dia memelihara domba peliharaannya (し) bersamanya. Sekarang satu-satunya wanita di kota ini adalah kakak perempuanmu, dan satu-satunya domba adalah hewan peliharaannya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
