INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('64d6561c-ea2f-448d-b69b-9325a7a27310', 'kanji', '思', '思', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Di sawah Anda menemukan hati dan itu membuat Anda berpikir. Kamu banyak berpikir seperti, "Hati siapa ini? Kenapa di sawah? Kenapa aku berpikir keras?"', 'Saat Anda memikirkan hal ini, Anda melihat seseorang di tepi sawah. Dia benar-benar mengingatkanmu pada seseorang. Tapi siapa? Itu saja! Dia mengingatkanmu pada bartender di The Simpsons. Siapa namanya? Anda berpikir lagi. Apa itu? Oh! Moe (おも) adalah namanya!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
