INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('41630936-df8f-4972-bfd4-d03503307c39', 'kanji', '持', '持', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Anda perlu melingkarkan jari Anda di sekitar pelipis jika ingin memegangnya. Apakah kuilnya terlalu besar? Ada juga kuil-kuil kecil yang bisa Anda beli di toko suvenir kuil.', 'Saat Anda memegang kuil, Anda mendengar suara. Anda melihat ke bawah melalui jari-jari Anda dan melihat Yesus kecil (じ). Dia tersenyum dan mengacungkan jempolnya padamu. Ah, terima kasih Yesus!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
