INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('b3cc1beb-bcec-47cf-a0ca-843bc906056d', 'kanji', '音', '音', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Untuk beberapa alasan, Anda berdiri di atas matahari. Ini jelas sangat panas, tapi hal yang paling Anda perhatikan adalah suara Anda terbakar.', 'Suara ini tidak hanya keras, tapi juga familier. Akhirnya Anda menempatkannya: bawang bombay (おん)!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
