INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('6034ce0d-13b2-4a67-8ee9-3929271f7ca2', 'kanji', '海', '海', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Tsunami akan datang, jadi arahkan senjatamu ke luar jendela. "Sebaiknya kau kembali, laut, atau aku akan menembak!"', 'Laut memutuskan tidak ingin mati hari ini, sehingga mengubah arah tsunaminya dan pergi ke arah lain. Anda naik kayak (かい) dan mengejarnya dengan senjata Anda, untuk memastikan kayak itu benar-benar kembali ke laut dan tidak menenggelamkan orang lain.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
