INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('688007ab-616f-4f11-ac69-e74e9a9a1663', 'kanji', '急', '急', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Hati serigala ada di penjara, jadi Anda harus segera membebaskannya. Tapi jangan terlalu mendadak, kalau tidak jantungnya tidak akan bertahan. Dan kematian serigala akan menimpamu.', 'Anda mencoba bergegas secepat mungkin untuk menyelamatkan serigala. Tapi kamu kehilangan kekuatan, jadi kamu ambil mentimun (きゅう) dari tasmu dan kunyahlah untuk mendapatkan kembali kekuatanmu yang terburu-buru.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
