INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('8583e778-cc4a-4a2f-8e73-73190b71cfd2', 'kanji', '映', '映', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Matahari yang berada di tengah langit memancarkan cahayanya, yang memantulkan segala sesuatu di sekitarnya.', 'Cahaya yang dipantulkan ini penting khususnya untuk biji pohon ek (えい). Tanpa cahaya yang memantulkan segala sesuatunya, cahaya matahari tidak akan pernah sampai ke tanah tempat mereka jatuh. Mereka tidak akan pernah tumbuh menjadi pohon. Dan kita semua akan mati lemas.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
