INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('1b2c4b31-02d3-4649-9a03-63c4f867664e', 'kanji', '建', '建', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kuas yoga ajaib Anda memungkinkan Anda membangun apa yang ada dalam pikiran Anda.', 'Anda membangun jembatan. Segera setelah itu, seseorang memanjat ke atasnya. Itu Ken (けん) sang samurai. Dia melambai ke arah Anda dan berkata, "Apakah Anda yang membuatnya? Keahliannya luar biasa."') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
