INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('444afba2-a4e4-447d-8e80-0296fca6614e', 'kanji', '研', '研', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Lentera batu adalah cara terbaik untuk mempertajam apa pun, bahkan dalam kegelapan. Pisaumu, garpumu, sendokmu, dan bahkan pedangmu.', 'Mengapa kamu mengasah pedangmu? Karena Anda akan bertempur dengan Ken (けん), prajurit samurai terkenal.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
