INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0d7f8c33-ef38-4053-8c75-79604c984584', 'さ', 'onyomi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('ee941b70-396e-4a52-a8e8-e02125aac2c0', 'kanji', '洋', '洋', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Seekor domba mengendarai tsunami dengan gaya klasik Barat. Yang saya maksud dengan gaya Barat adalah domba yang mengenakan pakaian koboi dan memasang pelana di atas gelombang tsunami untuk menungganginya. Itu adalah rodeo tsunami dan domba gila ini mengendarai gelombang tsunami dengan gaya klasik Barat. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ee941b70-396e-4a52-a8e8-e02125aac2c0', 'Gaya Barat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ee941b70-396e-4a52-a8e8-e02125aac2c0', 'Ocean', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ee941b70-396e-4a52-a8e8-e02125aac2c0', 'よう', 'onyomi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('a210c5a5-c45b-49b2-99b4-1b244cf978a6', 'kanji', '昼', '昼', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Matahari terbit dari tanah, dan di atasnya ada seekor udang raksasa. Ia tidak melakukan apa pun kecuali setiap hari tepat pada siang hari, saat ia memberi tahu Anda waktunya. "Hei kawan, ini sudah siang, mmk?"', 'Pada siang hari, udang juga mengenakan sepatu hak tinggi (ひる) untuk bersiap menghadapi malam hari, yang mana ia ingin memastikan penampilannya terlihat bagus untuk udang lain yang ditemuinya nanti.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
