INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a210c5a5-c45b-49b2-99b4-1b244cf978a6', 'ちゅう', 'onyomi', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a210c5a5-c45b-49b2-99b4-1b244cf978a6', 'ひる', 'kunyomi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('0c5449bc-67db-4653-9b37-1b0d3be05cf4', 'kanji', '家', '家', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Di bawah atap ini ada seekor babi. Babimu, karena itu rumahmu! Anda menyimpan babi Anda di dalam tempat yang nyaman dan hangat. Dia anggota keluargamu, jadi dia berhak tinggal di rumahmu juga.', 'Juga di rumahmu, ada mobilmu (か). Babi dan mobil Anda aman di bawah atap Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
