INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4ac7ed2c-7c5d-41d8-beba-949996056a48', 'vocabulary', '青い', '青い', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari biru? Itu masih biru! Ini juga bisa berarti mentah, yang mungkin terdengar membingungkan, tetapi hal ini disebabkan oleh fakta bahwa dalam bahasa Jepang ada beberapa kesamaan antara biru dan hijau. Jadi meskipun dalam bahasa Inggris kita menganggap lampu lalu lintas "pergi" dan pisang mentah sebagai "hijau", dalam bahasa Jepang keduanya disebut "biru".', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari biru? Itu masih biru! Ini juga bisa berarti mentah, yang mungkin terdengar membingungkan, tetapi hal ini disebabkan oleh fakta bahwa dalam bahasa Jepang ada beberapa kesamaan antara biru dan hijau. Jadi meskipun dalam bahasa Inggris kita menganggap lampu lalu lintas "pergi" dan pisang mentah sebagai "hijau", dalam bahasa Jepang keduanya disebut "biru".') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
