INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('af43a8e6-a451-48d1-8f5d-77f635a8eb2e', '二人の姉妹はとてもよくにています。', 'Kedua saudara perempuan itu sangat mirip.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('af43a8e6-a451-48d1-8f5d-77f635a8eb2e', '何か、二人って姉妹みたいだよね。', 'Hei, kalian berdua terlihat seperti saudara perempuan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('af43a8e6-a451-48d1-8f5d-77f635a8eb2e', '単なる女友達には無い絆が、姉妹の間にはある。', 'Ada ikatan antar saudara perempuan yang tidak dimiliki oleh gadis-gadis yang hanya berteman.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5d6bb009-b0c9-4c4e-8857-460d5357d230', 'vocabulary', '妹', '妹', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
