INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d6bb009-b0c9-4c4e-8857-460d5357d230', '田中さんの妹はどの人ですか。', 'Siapa adik perempuan Tanaka?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d6bb009-b0c9-4c4e-8857-460d5357d230', '妹にうら切られた気分です。', 'Aku merasa dikhianati oleh adik perempuanku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d6bb009-b0c9-4c4e-8857-460d5357d230', '私の妹は、バービー人形にウィッグを作ってあげたいからと、自分の髪の毛を切った。', 'Adik perempuan saya baru saja memotong seluruh rambutnya agar dia bisa membuat wig untuk boneka Barbie-nya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('711830bf-31e8-471d-b4d8-9d1245f68243', 'vocabulary', 'お姉さん', 'お姉さん', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Tanda お membuat kata tersebut lebih sopan. Kamu mengangkat gelar "kakak perempuan" karena kamu adalah adik yang baik. Kalau tidak, arti kata ini sama dengan kanji - hanya perasaannya saja yang berbeda. Anda juga dapat menggunakan kata ini untuk merujuk pada wanita berpenampilan muda yang tidak Anda kenal, seperti dalam "Permisi, Nona!"', 'Tanda お membuat kata tersebut lebih sopan. Kamu mengangkat gelar "kakak perempuan" karena kamu adalah adik yang baik. Kalau tidak, arti kata ini sama dengan kanji - hanya perasaannya saja yang berbeda. Anda juga dapat menggunakan kata ini untuk merujuk pada wanita berpenampilan muda yang tidak Anda kenal, seperti dalam "Permisi, Nona!"') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('711830bf-31e8-471d-b4d8-9d1245f68243', 'Kakak Perempuan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('711830bf-31e8-471d-b4d8-9d1245f68243', 'Miss', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('711830bf-31e8-471d-b4d8-9d1245f68243', 'おねえさん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('711830bf-31e8-471d-b4d8-9d1245f68243', 'みどりちゃんのお姉さんはめがねをかけています。', 'Kakak perempuan Midori memakai kacamata.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('711830bf-31e8-471d-b4d8-9d1245f68243', 'あなたのこと、てっきりビエトくんのお姉さんだと思ってたんですが、ちがったんですね。', 'Aku mengira kamu adalah kakak perempuan Viet, tapi ternyata bukan, ya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('711830bf-31e8-471d-b4d8-9d1245f68243', '私のお姉さんは、バイクを買うことが彼氏を見つけることに繋がると考えています。', 'Kakak perempuan saya berpikir bahwa membeli sepeda motor akan membantunya mendapatkan pacar.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c6ce1a4f-5743-4f24-9fe1-09c46feccf56', 'vocabulary', '思う', '思う', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berpikir, jadi versi verbanya adalah berpikir.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berpikir, jadi versi verbanya adalah berpikir.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
