INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c6ce1a4f-5743-4f24-9fe1-09c46feccf56', 'おもう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c6ce1a4f-5743-4f24-9fe1-09c46feccf56', 'かれも来ると思いますよ。', 'Menurutku dia juga akan datang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c6ce1a4f-5743-4f24-9fe1-09c46feccf56', 'ハリケーンのきせつはメキシコに行くのをさけた方がいいと思いますか。', 'Apakah menurut Anda saya sebaiknya menghindari pergi ke Meksiko selama musim badai?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c6ce1a4f-5743-4f24-9fe1-09c46feccf56', '思うだけならまだ違法じゃないよ。', 'Tindakan berpikir sederhana belumlah ilegal.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0818692d-addf-4cd0-9bb3-8dd236f25a39', 'vocabulary', '海', '海', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
