INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0818692d-addf-4cd0-9bb3-8dd236f25a39', '海で泳ぎました。', 'Saya pergi berenang di laut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0818692d-addf-4cd0-9bb3-8dd236f25a39', '海の公えんで、先生が学生に話しています。', 'Guru sedang berbicara dengan murid-muridnya di Taman Laut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0818692d-addf-4cd0-9bb3-8dd236f25a39', '映画「水の世界」は、実は、海の底に住んでいる超頭のいい魚によって書かれた作品だ。', 'Film Water World sebenarnya ditulis oleh ras ikan super cerdas yang hidup di dasar lautan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('aa67a689-2d32-466b-8742-f710e33a5a51', 'vocabulary', '海外', '海外', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Bagian luar laut ada di suatu tempat di luar negeri. Bisa juga asing atau luar negeri jika kata-kata itu lebih mudah Anda ingat.', 'Bagian luar laut ada di suatu tempat di luar negeri. Bisa juga asing atau luar negeri jika kata-kata itu lebih mudah Anda ingat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
