INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7c5f057e-2637-4c04-a4b0-69d32c314564', 'Teacher''s Office', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7c5f057e-2637-4c04-a4b0-69d32c314564', 'けんきゅうしつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7c5f057e-2637-4c04-a4b0-69d32c314564', 'わたしは子どもの時、研究室ではたらくのがゆめでした。', 'Ketika saya masih kecil, impian saya adalah bekerja di laboratorium.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7c5f057e-2637-4c04-a4b0-69d32c314564', 'くどいようですが、山田さんのかつらについて話すのは、この研究室ではタブーですからね。', 'Maaf jika saya mengulanginya lagi, tapi berbicara tentang wig Pak Yamada adalah hal yang tidak boleh dilakukan di ruang belajar ini, oke?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7c5f057e-2637-4c04-a4b0-69d32c314564', '蛙の解剖を始めるので、皆さんには研究室に移動して頂きたいと思います。', 'Saya ingin semua orang pindah ke laboratorium sekarang sehingga kita bisa mulai membedah katak tersebut.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e35b69bb-a1b0-45b0-bc46-b65e0daf27fe', 'vocabulary', '〜屋', '〜屋', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Anda akan melihatnya melekat pada kata lain... seperti "daging" atau "ikan". Saat Anda melihat ini, Anda akan tahu bahwa itu adalah ___ toko, sehingga kata ini berarti toko (sama seperti kanji).', 'Anda akan melihatnya melekat pada kata lain... seperti "daging" atau "ikan". Saat Anda melihat ini, Anda akan tahu bahwa itu adalah ___ toko, sehingga kata ini berarti toko (sama seperti kanji).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
