INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('57ef3aab-3b8b-4c5c-b5fa-8e96d8196a3f', 'Tea Store', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('57ef3aab-3b8b-4c5c-b5fa-8e96d8196a3f', 'Tea House', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('57ef3aab-3b8b-4c5c-b5fa-8e96d8196a3f', 'ちゃや', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('57ef3aab-3b8b-4c5c-b5fa-8e96d8196a3f', 'ポートランドでは、トーフグ茶屋の、ふぐもちが人気です。', 'Toko teh Tofugu di Portland memiliki fugu mochi yang populer.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('57ef3aab-3b8b-4c5c-b5fa-8e96d8196a3f', 'きょうとにりょ行したとき、コウイチは毎ばん茶屋あそびを楽しみました。', 'Saat Koichi bepergian ke Kyoto, dia menikmati hiburan kedai teh setiap malam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('57ef3aab-3b8b-4c5c-b5fa-8e96d8196a3f', '日本人は現代的なカフェを「カフェ」、昭和の香りのするコーヒーラウンジを「喫茶店」、伝統的なお茶屋さんを「茶屋」と呼びます。', 'Orang Jepang menyebut kafe modern sebagai "Kafe", ruang minum kopi yang agak kuno dengan sebutan "Kissaten", dan kedai teh tradisional dengan sebutan "Chaya".') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('43fba0f6-2b6f-4c31-b178-2eb2e6e30835', 'vocabulary', '名古屋', '名古屋', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Tempat yang terkenal dengan atap-atap tua. Saya tidak tahu kenapa, tapi ini kota Nagoya. Gabungkan saja kedua hal tersebut dan Anda akan sulit untuk melupakannya (selama Anda pernah mendengar tentang Nagoya sebelumnya - jika belum, bacalah tentangnya!).', 'Tempat yang terkenal dengan atap-atap tua. Saya tidak tahu kenapa, tapi ini kota Nagoya. Gabungkan saja kedua hal tersebut dan Anda akan sulit untuk melupakannya (selama Anda pernah mendengar tentang Nagoya sebelumnya - jika belum, bacalah tentangnya!).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('43fba0f6-2b6f-4c31-b178-2eb2e6e30835', 'Nagoya', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('43fba0f6-2b6f-4c31-b178-2eb2e6e30835', 'なごや', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('43fba0f6-2b6f-4c31-b178-2eb2e6e30835', '名古屋にはおいしいものがたくさんあります。', 'Nagoya punya banyak makanan enak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('43fba0f6-2b6f-4c31-b178-2eb2e6e30835', '今日も名古屋で仕事があった。', 'Saya harus bekerja di Nagoya hari ini lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('43fba0f6-2b6f-4c31-b178-2eb2e6e30835', '名古屋にいる友人を訪れた際、矢場とんというとても美味しいトンカツをご馳走してもらいました。', 'Saat saya mengunjungi teman saya di Nagoya, saya disuguhi potongan daging babi lezat bernama yabaton.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b0457fb6-e5df-49a3-b9da-251adc5de64b', 'vocabulary', '今度', '今度', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Sekarang kamu akan mempelajari kanjimu, bukan? Kata ini berarti kali ini. Meski "kali ini", namun ada perasaan lain kali. Ini seperti mengatakan "oke, kali ini kita akan mendapatkannya" sedangkan "kali ini" sebenarnya berarti "lain kali", membuatnya sedikit berbeda dari 今回.', 'Sekarang kamu akan mempelajari kanjimu, bukan? Kata ini berarti kali ini. Meski "kali ini", namun ada perasaan lain kali. Ini seperti mengatakan "oke, kali ini kita akan mendapatkannya" sedangkan "kali ini" sebenarnya berarti "lain kali", membuatnya sedikit berbeda dari 今回.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
