INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b0457fb6-e5df-49a3-b9da-251adc5de64b', 'じゃあ、やっぱり今度にしよう。', 'Oke, kalau begitu mari kita lakukan lain kali.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b0457fb6-e5df-49a3-b9da-251adc5de64b', '今度は本当に本気の本気で日本ごをべんきょうします！', 'Saya sungguh-sungguh serius mempelajari bahasa Jepang kali ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b0457fb6-e5df-49a3-b9da-251adc5de64b', '今度俺がお前を泣かせる時は、嬉し泣きだ。', 'Lain kali aku membuatmu menangis, itu karena kamu bahagia.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('10d2e96b-dde9-428a-8348-cf18553a4f97', 'vocabulary', '毎度', '毎度', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ketika sesuatu terjadi pada setiap kejadian dan pada tingkat apa pun, itu adalah sesuatu yang sering terjadi. Itu terjadi setiap saat.', 'Ketika sesuatu terjadi pada setiap kejadian dan pada tingkat apa pun, itu adalah sesuatu yang sering terjadi. Itu terjadi setiap saat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
