INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('10d2e96b-dde9-428a-8348-cf18553a4f97', '毎度おさわがせして、申しわけありません。', 'Aku minta maaf atas semua waktu yang telah merepotkanmu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('10d2e96b-dde9-428a-8348-cf18553a4f97', '毎度のことだが、空は今日もちゅう文を決めるのがおそい。', 'Sora tidak bisa memutuskan mana yang harus dipesan, seperti biasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('10d2e96b-dde9-428a-8348-cf18553a4f97', '毎度有難う御座います。', 'Terima kasih atas dukungan Anda yang berkelanjutan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6eb818a1-cf04-4d86-ab0e-4a17f44c57c8', 'vocabulary', '〜度', '〜度', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Derajat kanji dapat berarti derajat dalam hal sudut dan derajat dalam hal suhu. Kata ini adalah cara Anda membicarakan hal-hal ini. Lampirkan saja ke sebuah angka dan Anda akan mendapatkan sendiri jumlah derajat sesuatu itu. Setelah angka 1, 2 dan 3 (dan dalam beberapa situasi lainnya) ini juga bisa berarti waktu.', 'Derajat kanji dapat berarti derajat dalam hal sudut dan derajat dalam hal suhu. Kata ini adalah cara Anda membicarakan hal-hal ini. Lampirkan saja ke sebuah angka dan Anda akan mendapatkan sendiri jumlah derajat sesuatu itu. Setelah angka 1, 2 dan 3 (dan dalam beberapa situasi lainnya) ini juga bisa berarti waktu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
