INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6eb818a1-cf04-4d86-ab0e-4a17f44c57c8', 'ど', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6eb818a1-cf04-4d86-ab0e-4a17f44c57c8', '弟は、かぜで38度のねつがあります。', 'Adik saya sedang flu dan demam 38 derajat celcius.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6eb818a1-cf04-4d86-ab0e-4a17f44c57c8', 'エアコンのおん度はいつも何度ぐらいにしていますか？', 'Berapa suhu yang biasa Anda atur pada AC?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6eb818a1-cf04-4d86-ab0e-4a17f44c57c8', '２４度ぐらいがちょうどいいと思うんだけど。', 'Menurutku suhu 24 derajat tepat untukku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('362f8fee-1221-4b8f-9fd5-19e7be6f5fa0', 'vocabulary', '待つ', '待つ', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menunggu, jadi versi verbanya adalah menunggu.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menunggu, jadi versi verbanya adalah menunggu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('362f8fee-1221-4b8f-9fd5-19e7be6f5fa0', 'Untuk Menunggu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('362f8fee-1221-4b8f-9fd5-19e7be6f5fa0', 'まつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('362f8fee-1221-4b8f-9fd5-19e7be6f5fa0', 'きっ茶店で、五時間待っていましたが、かれは来ませんでした。', 'Saya menunggu selama lima jam di kafe, tetapi dia tidak datang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('362f8fee-1221-4b8f-9fd5-19e7be6f5fa0', 'スタバで待ってますね。', 'Aku akan menunggumu di Starbucks.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('362f8fee-1221-4b8f-9fd5-19e7be6f5fa0', 'ちょっと待って！財布を家に忘れたかも。', 'Tunggu! Saya mungkin lupa dompet saya di rumah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9cb950d3-9c14-4e0a-9f12-c198c77029af', 'vocabulary', '待たせる', '待たせる', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menunggu, jadi kata ini ada kaitannya dengan menunggu. Gunakan たせ sebagai petunjuk. Seseorang "melempar" bola ke dalam selokan, dan kemudian mereka harus menemukannya. Mereka membuatmu menunggu sampai mereka mendapatkan bolanya juga, padahal itu omong kosong yang murah. Merasa kesal tentang hal ini. Itu akan membantu Anda mengingat bahwa ini berarti membuat seseorang menunggu dan membuat seseorang menunggu.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menunggu, jadi kata ini ada kaitannya dengan menunggu. Gunakan たせ sebagai petunjuk. Seseorang "melempar" bola ke dalam selokan, dan kemudian mereka harus menemukannya. Mereka membuatmu menunggu sampai mereka mendapatkan bolanya juga, padahal itu omong kosong yang murah. Merasa kesal tentang hal ini. Itu akan membantu Anda mengingat bahwa ini berarti membuat seseorang menunggu dan membuat seseorang menunggu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9cb950d3-9c14-4e0a-9f12-c198c77029af', 'Untuk Membuat Seseorang Menunggu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9cb950d3-9c14-4e0a-9f12-c198c77029af', 'To Keep Someone Waiting', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9cb950d3-9c14-4e0a-9f12-c198c77029af', 'またせる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9cb950d3-9c14-4e0a-9f12-c198c77029af', '先ぱいを待たせるのはよくないよ。', 'Tidak baik membiarkan senpaimu menunggu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9cb950d3-9c14-4e0a-9f12-c198c77029af', '一体何時まで待たせるつもりですか？', 'Berapa lama lagi kamu akan membuatku menunggu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9cb950d3-9c14-4e0a-9f12-c198c77029af', 'お待たせしてすみません。いや〜バスにえらく長いこと待たされましてね。', 'Maaf telah membuatmu menunggu begitu lama. Saya harus menunggu bus begitu lama.') ON CONFLICT DO NOTHING;
