INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ea500731-2875-415d-ac33-87e3a076e779', 'あらきさんは、けしゴムを持っていますか？', 'Apakah kamu punya penghapus, Araki?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ea500731-2875-415d-ac33-87e3a076e779', 'コウイチは、実はなんしきやきゅうしんぱん員のしかくを持っています...というのは実はうそです。', 'Sebenarnya Koichi punya izin menjadi wasit soft baseball...sebenarnya itu bohong.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ea500731-2875-415d-ac33-87e3a076e779', '一等に当選したことを知った時、宝くじを持つ手の震えが止まらなかった。', 'Ketika saya menyadari bahwa saya memenangkan hadiah utama, tangan saya yang memegang tiket lotre tidak dapat menahan diri untuk tidak gemetar.') ON CONFLICT DO NOTHING;
