INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f2fd495e-66d9-47d5-bab8-ae3648536dcb', 'あなたの気持ちはよく分かります。', 'Saya tahu persis bagaimana perasaan Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f2fd495e-66d9-47d5-bab8-ae3648536dcb', '気持ちがわるくてはきそうです。', 'Aku merasa mual, seperti mau muntah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f2fd495e-66d9-47d5-bab8-ae3648536dcb', 'これ、つまらないものですが。ささやかな感謝の気持ちです。どうぞ、開けてみてください。', 'Ini ada sesuatu untuk Anda. Ini hanyalah bentuk kecil dari apresiasi saya. Silakan, buka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('712bd47a-1255-4b17-970d-109e7a8c9b4e', 'vocabulary', '世界', '世界', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Generasi (dan masyarakat!) yang membentuk dunia menciptakan dunia kita. Jadi inilah Dunia, masyarakat, atau Alam Semesta.　
