INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dc20b25c-74b9-46df-8960-e69bc810f253', 'アンナさんの体重は、何キロですか？', 'Berapa berat badan Anna dalam kilogram?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dc20b25c-74b9-46df-8960-e69bc810f253', '次の身体そく定で体重をはかるのが待ちきれない。', 'Saya tidak sabar untuk menimbang diri saya pada pengukuran tubuh berikutnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dc20b25c-74b9-46df-8960-e69bc810f253', 'どうして私があなたの体重を知っているのか聞かないで。ジェシカが口を滑らせたことは絶対に誰にも言わないって、あの子と約束したんだから。', 'Jangan tanya saya bagaimana saya tahu berat badan Anda. Aku berjanji pada Jessica bahwa aku tidak akan memberitahumu apa yang dia katakan padaku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ebfbb8d5-0146-45a5-977e-b56f6353145f', 'vocabulary', '二重', '二重', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ketika Anda memiliki dua benda berat, Anda memiliki beban ganda dan ganda (setidaknya dibandingkan dengan satu). 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ebfbb8d5-0146-45a5-977e-b56f6353145f', 'Ganda', true) ON CONFLICT DO NOTHING;
