INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ebfbb8d5-0146-45a5-977e-b56f6353145f', 'にじゅう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ebfbb8d5-0146-45a5-977e-b56f6353145f', '分からないかん字の下に、二重せんを引いてください。', 'Silakan menggambar garis ganda di bawah kanji yang Anda tidak tahu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ebfbb8d5-0146-45a5-977e-b56f6353145f', '日本は二重国せきをみとめていません。', 'Jepang tidak mengizinkan kewarganegaraan ganda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ebfbb8d5-0146-45a5-977e-b56f6353145f', '「それでは、世間話はそれぐらいにして、本題に入ろう。今日の議題は何だったかな？」「今日はあなたの二重あごについて話しをすることになっています。」「そうだったな。それでは始めようか。」', '“Baiklah, mari kita hentikan obrolan ringan dan langsung saja ke pokok permasalahan. Apa topik pertemuan hari ini?” "Tadinya kami akan membicarakan dagu ganda Anda, Tuan." “Benar, benar. Mari kita mulai.”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9c5f20ad-d89f-41e6-ae50-99029f2ae6ea', 'vocabulary', '洋風', '洋風', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ingat bagaimana 風 bisa berarti "gaya" seperti dalam 和風? Nah, ini sekarang gaya gaya Barat, lebih sederhananya gaya Barat.', 'Ingat bagaimana 風 bisa berarti "gaya" seperti dalam 和風? Nah, ini sekarang gaya gaya Barat, lebih sederhananya gaya Barat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9c5f20ad-d89f-41e6-ae50-99029f2ae6ea', 'Gaya Barat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9c5f20ad-d89f-41e6-ae50-99029f2ae6ea', 'ようふう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c5f20ad-d89f-41e6-ae50-99029f2ae6ea', '今日の夕食は、洋風ポトフです。', 'Makan malam malam ini adalah pot‐au‐feu gaya Barat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c5f20ad-d89f-41e6-ae50-99029f2ae6ea', '洋風なかんじのオシャレな曲が、洋風のカフェでながれていた。', 'Lagu gaya barat yang halus dimainkan di kafe gaya Barat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c5f20ad-d89f-41e6-ae50-99029f2ae6ea', '私の家は、家具を全て洋風に揃えているので、畳はありません。', 'Rumah saya seluruhnya dilengkapi dengan gaya Barat, jadi tidak ada tikar tatami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('877256a0-8066-4ac5-9240-5bffb7ef14fe', 'vocabulary', '洋服', '洋服', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Pakaian gaya barat hanyalah pakaian Barat (atau pakaian gaya Barat). Namun saat ini, karena orang Jepang selalu memakai pakaian Barat, kami menggunakannya hanya untuk memaksudkan pakaian. Kami membicarakan hal-hal yang bukan kimono, dll.', 'Pakaian gaya barat hanyalah pakaian Barat (atau pakaian gaya Barat). Namun saat ini, karena orang Jepang selalu memakai pakaian Barat, kami menggunakannya hanya untuk memaksudkan pakaian. Kami membicarakan hal-hal yang bukan kimono, dll.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('877256a0-8066-4ac5-9240-5bffb7ef14fe', 'Pakaian', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('877256a0-8066-4ac5-9240-5bffb7ef14fe', 'Western Clothing', false) ON CONFLICT DO NOTHING;
