INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d19bd2bc-395f-4309-b354-1e004d66837a', '見送る方と見送られる方って、どっちの方がつらいんだろうね。', 'Aku bertanya-tanya mana yang lebih sulit, menjadi orang yang mengantar seseorang atau menjadi orang yang diantar oleh seseorang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d19bd2bc-395f-4309-b354-1e004d66837a', 'コウイチは、彼らを見送った後、どっと涙の雨を流した。', 'Koichi menangis setelah melihat mereka pergi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d19bd2bc-395f-4309-b354-1e004d66837a', '彼は海外に行くチャンスを見送った。', 'Dia melewatkan kesempatan untuk pergi ke luar negeri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b662c80a-8bf7-4db2-984e-c59a1a1b04d3', 'vocabulary', '音読み', '音読み', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Pembacaan suara. Apa ini...? Tunggu sebentar, pikirkan bahasa Jepang dan kanji. Bacaan apa yang menggunakan bunyi-bunyian dari tempat lain, khususnya Tiongkok? Itu bacaan Cina alias on''yomi. Kedengarannya familier?', 'Pembacaan suara. Apa ini...? Tunggu sebentar, pikirkan bahasa Jepang dan kanji. Bacaan apa yang menggunakan bunyi-bunyian dari tempat lain, khususnya Tiongkok? Itu bacaan Cina alias on''yomi. Kedengarannya familier?') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
