INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b662c80a-8bf7-4db2-984e-c59a1a1b04d3', 'On''yomi', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b662c80a-8bf7-4db2-984e-c59a1a1b04d3', 'おんよみ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b662c80a-8bf7-4db2-984e-c59a1a1b04d3', 'この漢字の音読みって何だっけ？', 'Apa on''yomi untuk kanji ini lagi?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b662c80a-8bf7-4db2-984e-c59a1a1b04d3', '初めて見た地名はふ通は音読みしちゃうよね。', 'Biasanya kita membaca nama tempat yang pertama kali kita lihat dengan on''yomi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b662c80a-8bf7-4db2-984e-c59a1a1b04d3', '日本語の音読みと訓読みの違いは何ですか？', 'Apa perbedaan antara bacaan Cina dan bacaan Jepang dalam bahasa Jepang?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6a7c6a9a-db63-4066-aeba-56e643950f82', 'vocabulary', '映る', '映る', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya mencerminkan. Versi vocab verbanya berarti direfleksikan. Anda tidak melakukan refleksi secara langsung. Anda dapat mengingat hal ini dengan memikirkan betapa kasarnya (る) ketika seseorang memantulkan bayangan Anda menggunakan cermin agar semua orang di luar ruang ganti dapat melihatnya.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya mencerminkan. Versi vocab verbanya berarti direfleksikan. Anda tidak melakukan refleksi secara langsung. Anda dapat mengingat hal ini dengan memikirkan betapa kasarnya (る) ketika seseorang memantulkan bayangan Anda menggunakan cermin agar semua orang di luar ruang ganti dapat melihatnya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
