INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7a3a3549-45ae-45f5-a21b-7384c0f25c01', 'もうジブリの最新映画は見ましたか。', 'Apakah kamu sudah menonton film Ghibli terbaru?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7a3a3549-45ae-45f5-a21b-7384c0f25c01', 'わたしはロマンス映画が好きなのに、主人は戦争映画ばっかり見たがるんです。', 'Walaupun saya suka film romantis, suami saya hanya ingin menonton film perang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7a3a3549-45ae-45f5-a21b-7384c0f25c01', '「僕は映画スターになって、自家用ジェット機を買うよ。それから、君は僕のお嫁さんになるんだ。」 「おじいちゃん、何寝ぼけたこと言ってんの。」', '“Saya akan menjadi bintang film, membeli jet pribadi, dan Anda akan menjadi istri saya.” "Ya, bermimpilah, kakek."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bf752cfc-22c1-432b-8743-6521aa525f44', 'vocabulary', '建てる', '建てる', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya membangun jadi versi vocab verbanya adalah membangun.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya membangun jadi versi vocab verbanya adalah membangun.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bf752cfc-22c1-432b-8743-6521aa525f44', 'Untuk Membangun', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bf752cfc-22c1-432b-8743-6521aa525f44', 'To Construct', false) ON CONFLICT DO NOTHING;
