INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bf752cfc-22c1-432b-8743-6521aa525f44', 'この男は、とても丈夫な家を建てることで有名です。', 'Pria ini terkenal membangun rumah yang sangat kokoh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bf752cfc-22c1-432b-8743-6521aa525f44', 'その王は、山の上に信じられないほど美しいおしろを建てました。', 'Raja membangun sebuah kastil yang luar biasa indah di puncak gunung.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bf752cfc-22c1-432b-8743-6521aa525f44', '我が社は、外国の子どもたちに学校を建ててあげるために貯金をしています。', 'Perusahaan kami menabung uang untuk membangun sekolah bagi anak-anak di negara lain.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('919acbd4-9300-4c5f-bc82-8eedc1ffb553', 'vocabulary', '春', '春', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('919acbd4-9300-4c5f-bc82-8eedc1ffb553', 'Musim semi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('919acbd4-9300-4c5f-bc82-8eedc1ffb553', 'はる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('919acbd4-9300-4c5f-bc82-8eedc1ffb553', 'わたしは虫が苦手だから春はきらいです。', 'Saya tidak suka serangga, jadi saya tidak suka musim semi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('919acbd4-9300-4c5f-bc82-8eedc1ffb553', '「お前のチーム、春の大会ではどうだったの？」「へへ。大勝したっての！」', '“Bagaimana kinerja timmu di turnamen musim semi?” “Hehe. Kemenangan epik.”') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('919acbd4-9300-4c5f-bc82-8eedc1ffb553', '春巻きという料理に「春」の字が使われているのは、春に芽が出る野菜を使って作る食べ物だかららしいですよ。', 'Saya mendengar alasan penggunaan karakter "musim semi" untuk lumpia adalah karena orang biasa membuat lumpia dengan sayuran yang bertunas di musim semi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('63c9f85b-6515-4f51-aea9-a0834e4a2043', 'vocabulary', '春休み', '春休み', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Anda pernah melihat 夏休み dan 冬休み. Jika itu belum cukup, Anda dapat melihat bahwa ini adalah semacam istirahat musim semi. Itu akan menjadi liburan musim semi atau liburan musim semi.', 'Anda pernah melihat 夏休み dan 冬休み. Jika itu belum cukup, Anda dapat melihat bahwa ini adalah semacam istirahat musim semi. Itu akan menjadi liburan musim semi atau liburan musim semi.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('63c9f85b-6515-4f51-aea9-a0834e4a2043', 'liburan musim semi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('63c9f85b-6515-4f51-aea9-a0834e4a2043', 'Spring Vacation', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('63c9f85b-6515-4f51-aea9-a0834e4a2043', 'Spring Holiday', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('63c9f85b-6515-4f51-aea9-a0834e4a2043', 'はるやすみ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('63c9f85b-6515-4f51-aea9-a0834e4a2043', '春休みキャンペーン期間中は、学生の入場料は一りつ千円です。', 'Selama promosi liburan musim semi, tiket masuk hanya 1.000 yen untuk pelajar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('63c9f85b-6515-4f51-aea9-a0834e4a2043', '春休み中だったら、この時間たいは空いてます。', 'Saat-saat selama liburan musim semi ini akan berhasil untuk saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('63c9f85b-6515-4f51-aea9-a0834e4a2043', 'そろそろ風邪治った？春休みに風邪引くなんて最悪だよね。もしまだ辛いなら、夜更かししちゃだめだよ。早く良くなってね。', 'Apakah kamu sudah mengatasi flumu? Sungguh menyebalkan masuk angin saat liburan musim semi, ya? Kalau masih jelek, jangan begadang. Semoga segera sembuh.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4629d5db-baaa-497f-bfb4-f543702141a0', 'vocabulary', '昼', '昼', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Ini juga bisa berarti makan siang, terutama bila digunakan dengan awalan kehormatan お, seperti dalam お昼.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Ini juga bisa berarti makan siang, terutama bila digunakan dengan awalan kehormatan お, seperti dalam お昼.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4629d5db-baaa-497f-bfb4-f543702141a0', 'Siang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4629d5db-baaa-497f-bfb4-f543702141a0', 'Lunch', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4629d5db-baaa-497f-bfb4-f543702141a0', 'ひる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4629d5db-baaa-497f-bfb4-f543702141a0', '今日の昼、あそこの定食屋でお昼一しょに食べようよ。', 'Mengapa kita tidak makan siang bersama di restoran itu saat istirahat makan siang hari ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4629d5db-baaa-497f-bfb4-f543702141a0', '目ざまし時計が鳴らなくて、起きたらすでに昼だった。', 'Alarmku tidak berbunyi dan hari sudah siang ketika aku bangun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4629d5db-baaa-497f-bfb4-f543702141a0', '今から一時間昼休憩を取るので、電話は取り次がないようにしてください。', 'Saya akan istirahat makan siang selama satu jam, jadi tolong tahan telepon saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9df50609-4251-4b54-bee0-ac0b1c6f9d0a', 'vocabulary', '秋', '秋', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9df50609-4251-4b54-bee0-ac0b1c6f9d0a', 'Musim gugur', true) ON CONFLICT DO NOTHING;
