INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71898150-a2d4-4f55-9735-32da8ceb7d15', 'コウイチはビエトにもらった時計を船から落としてしまいました。', 'Koichi menjatuhkan jam yang diberikan Viet dari kapal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71898150-a2d4-4f55-9735-32da8ceb7d15', '時計台の下で、三時に待ち合わせね！', 'Kita akan bertemu di menara jam jam 3 sore, oke?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71898150-a2d4-4f55-9735-32da8ceb7d15', 'ねぇ、あなたの時計に唾が着いてない？', 'Hei, bukankah itu meludahi jam tanganmu?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('14a7f30c-cbe7-4de8-85ee-bd72fa5d848e', 'vocabulary', '計画', '計画', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Saat Anda menggambar pengukuran yang ingin Anda lakukan di papan tulis, Anda sedang menyusun rencana untuk melakukan sesuatu. Segala sesuatu memerlukan semacam pengukuran, jadi menyusun pengukuran itu adalah rencana Anda.', 'Saat Anda menggambar pengukuran yang ingin Anda lakukan di papan tulis, Anda sedang menyusun rencana untuk melakukan sesuatu. Segala sesuatu memerlukan semacam pengukuran, jadi menyusun pengukuran itu adalah rencana Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
