INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0779c47f-8a17-4cd7-b708-791ec38502b3', '私は下品な英語の基本をマスターしました。', 'Saya telah menguasai dasar-dasar bahasa Inggris vulgar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0779c47f-8a17-4cd7-b708-791ec38502b3', 'はるか遠くから、下品な笑い声が聞こえてきた。', 'Saya mendengar tawa vulgar dari kejauhan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0779c47f-8a17-4cd7-b708-791ec38502b3', 'あなたの下品なメールは会社に戻ってからじっくり読ませてもらいます。', 'Saya akan membaca email kasar Anda dengan cermat ketika saya kembali ke kantor.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('06e52c38-1122-478b-a515-2787c3d84a21', 'vocabulary', '作品', '作品', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Jika Anda membuat suatu produk, sebenarnya itu bukan lagi sebuah produk, melainkan sebuah karya. Itu karya seni atau sastra Anda, atau mungkin produksi teater.
