INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('32f506dd-d809-4ba6-b6ef-e59464728a17', '急に空からマッチ箱が一箱ふってきたんです。', 'Sebuah kotak korek api tiba-tiba jatuh dari langit.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('32f506dd-d809-4ba6-b6ef-e59464728a17', 'えっ、クリステン！急にそんなことを言われても、困るよ...。', 'Oh Kristen! Biarpun kamu langsung memberitahuku hal seperti itu, aku bingung...') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('32f506dd-d809-4ba6-b6ef-e59464728a17', 'ファミリー・ガイは、急に馬鹿げた回想シーンを使うことで良く知られている。', 'Family Guy terkenal dengan kilas baliknya yang acak dan bodoh.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ec25c83e-521b-40c3-a525-fca20040b443', 'vocabulary', '急死', '急死', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kematian mendadak berarti kematian mendadak.', 'Kematian mendadak berarti kematian mendadak.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
