INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ec25c83e-521b-40c3-a525-fca20040b443', 'きゅうし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ec25c83e-521b-40c3-a525-fca20040b443', '父が急死した時、私は受けん生でした。', 'Saya sedang bersiap untuk mengikuti ujian ketika ayah saya tiba-tiba meninggal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ec25c83e-521b-40c3-a525-fca20040b443', '昨日、上司が、のう出血のため急死しました。', 'Atasan saya meninggal mendadak karena pendarahan otak kemarin.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ec25c83e-521b-40c3-a525-fca20040b443', '彼とはよく喧嘩になっちゃって、それが本当に嫌だったんだけど、今では喧嘩もできなくなっちゃってすっごく悲しいよ。まさか心臓発作で急死しちゃうなんて思ってもみなかったからさ。', 'Aku sering berdebat dengan pacarku dan aku membencinya, tapi aku malah merindukan pertengkaran itu sekarang. Saya tidak pernah menyangka dia akan mati karena serangan jantung.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dbbe3c85-0f82-4638-bfde-51876ac81a7e', 'vocabulary', '急行', '急行', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Hal-hal yang terburu-buru dan berjalan lebih cepat dibandingkan hal-hal lain yang diungkapkan. Ini sering digunakan pada kereta api atau kereta bawah tanah, jadi berhati-hatilah jika Anda ingin pergi ke suatu tempat dengan tergesa-gesa. Berhati-hatilah juga jika kereta tidak berhenti di halte Anda, karena 急行 kereta tidak berhenti di setiap stasiun (yang membuatnya menjadi ekspres!).', 'Hal-hal yang terburu-buru dan berjalan lebih cepat dibandingkan hal-hal lain yang diungkapkan. Ini sering digunakan pada kereta api atau kereta bawah tanah, jadi berhati-hatilah jika Anda ingin pergi ke suatu tempat dengan tergesa-gesa. Berhati-hatilah juga jika kereta tidak berhenti di halte Anda, karena 急行 kereta tidak berhenti di setiap stasiun (yang membuatnya menjadi ekspres!).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('dbbe3c85-0f82-4638-bfde-51876ac81a7e', 'Ekspres', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('dbbe3c85-0f82-4638-bfde-51876ac81a7e', 'きゅうこう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dbbe3c85-0f82-4638-bfde-51876ac81a7e', 'けいさつは、はんざいげん場へ急行しました。', 'Petugas polisi bergegas ke TKP.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dbbe3c85-0f82-4638-bfde-51876ac81a7e', '私にやさしくしてくれた人たちに、急行便でお礼の品を送りました。', 'Saya mengirimkan hadiah terima kasih secara kilat kepada orang-orang yang baik kepada saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dbbe3c85-0f82-4638-bfde-51876ac81a7e', 'あーーーしまったーーーー。急行列車が行ってしまった。ってことは私の遅刻も確定だ。コウイチから受ける処罰がすんごく怖いんですけど。', 'Oh tidaaaak! Kereta ekspres berangkat. Sekarang aku akan terlambat. Aku sangat takut dihukum oleh Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('35944b9d-f242-4800-86de-8856a88cae20', 'vocabulary', '映す', '映す', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Anda tahu bahwa 映る adalah "untuk direfleksikan." Sekarang Anda sedang melakukan refleksi, yang sebenarnya memproyeksikan (cahaya). Itu sebabnya kata ini memproyeksikan.', 'Anda tahu bahwa 映る adalah "untuk direfleksikan." Sekarang Anda sedang melakukan refleksi, yang sebenarnya memproyeksikan (cahaya). Itu sebabnya kata ini memproyeksikan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('35944b9d-f242-4800-86de-8856a88cae20', 'Untuk Memproyeksikan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('35944b9d-f242-4800-86de-8856a88cae20', 'To Reflect', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('35944b9d-f242-4800-86de-8856a88cae20', 'うつす', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('35944b9d-f242-4800-86de-8856a88cae20', 'スクリーンにスライドを映し始めてもらえますか？', 'Bisakah Anda mulai memproyeksikan slide ke layar untuk saya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('35944b9d-f242-4800-86de-8856a88cae20', 'この白いかべをスクリーン代わりにして映画を映すのはどうでしょう。', 'Mengapa kita tidak menggunakan dinding putih ini sebagai layar untuk memproyeksikan filmnya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('35944b9d-f242-4800-86de-8856a88cae20', 'ビエトだけが、コウイチが鏡に全身を映すのが好きだということを知っている。', 'Hanya Viet yang tahu bahwa Koichi sangat suka melihat dirinya terpantul di cermin.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0f0fb56e-ce1e-4a78-9144-ef574df11449', 'vocabulary', '気持ちいい', '気持ちいい', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Saat Anda mempunyai perasaan (気持ち) yaitu いい (yang artinya "baik"), Anda mempunyai perasaan yang baik.', 'Saat Anda mempunyai perasaan (気持ち) yaitu いい (yang artinya "baik"), Anda mempunyai perasaan yang baik.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0f0fb56e-ce1e-4a78-9144-ef574df11449', 'Perasaan Baik', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0f0fb56e-ce1e-4a78-9144-ef574df11449', 'Feeling Good', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0f0fb56e-ce1e-4a78-9144-ef574df11449', 'Feels Good', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0f0fb56e-ce1e-4a78-9144-ef574df11449', 'きもちいい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0f0fb56e-ce1e-4a78-9144-ef574df11449', 'この羽毛ぶとん、気持ちいい。', 'Selimut bulu ini terasa sangat enak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0f0fb56e-ce1e-4a78-9144-ef574df11449', '家がきれいだと気持ちいいよね！', 'Bukankah menyenangkan memiliki rumah yang bersih?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0f0fb56e-ce1e-4a78-9144-ef574df11449', 'このマッサージ、気持ちいい。このいた気持ちよさがたまらない。', 'Pijatan ini terasa enak. Saya menikmati rasa sakit yang luar biasa ini!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f3434e4e-3adf-44f2-81f1-0ac8b497d832', 'vocabulary', '建つ', '建つ', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Anda tahu bahwa 建てる berarti "membangun". Ini mirip dengan itu, tetapi ini adalah versi di mana Anda tidak melakukan pembangunannya. Sesuatu baru saja dibangun. Itulah sebabnya firman ini didirikan dan dibangun. Anda dapat mengenalinya karena つ, yang memberi tahu Anda bahwa dua orang (つ) sedang membangun gedung saat Anda menonton. Jadi Anda tidak melakukannya, mereka melakukannya, dan itu terjadi begitu saja.', 'Anda tahu bahwa 建てる berarti "membangun". Ini mirip dengan itu, tetapi ini adalah versi di mana Anda tidak melakukan pembangunannya. Sesuatu baru saja dibangun. Itulah sebabnya firman ini didirikan dan dibangun. Anda dapat mengenalinya karena つ, yang memberi tahu Anda bahwa dua orang (つ) sedang membangun gedung saat Anda menonton. Jadi Anda tidak melakukannya, mereka melakukannya, dan itu terjadi begitu saja.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f3434e4e-3adf-44f2-81f1-0ac8b497d832', 'Akan Didirikan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f3434e4e-3adf-44f2-81f1-0ac8b497d832', 'To Be Built', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f3434e4e-3adf-44f2-81f1-0ac8b497d832', 'たつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3434e4e-3adf-44f2-81f1-0ac8b497d832', '東京には、新しい高そうビルがぞくぞくと建っています。', 'Gedung-gedung tinggi baru sedang dibangun satu demi satu di Tokyo.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3434e4e-3adf-44f2-81f1-0ac8b497d832', 'ホワイトハウスに、コウイチのどうぞうが建ちました。', 'Patung perunggu Koichi didirikan di Gedung Putih.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3434e4e-3adf-44f2-81f1-0ac8b497d832', 'サーモンと僕は、浜辺の北端に建つ家を買おうと相談してるんですが、ちょっと私達には値段が高いんですよね。', 'Salmon dan saya sedang berdiskusi untuk membeli rumah siap pakai di ujung utara pantai, tapi harganya agak mahal bagi kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('41797880-6724-42f5-81f2-dfa5588c4768', 'vocabulary', '建物', '建物', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Sesuatu yang Anda bangun adalah sebuah bangunan. Tidak banyak hal lain yang Anda bangun, setidaknya tidak sampai sejauh ini.', 'Sesuatu yang Anda bangun adalah sebuah bangunan. Tidak banyak hal lain yang Anda bangun, setidaknya tidak sampai sejauh ini.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('41797880-6724-42f5-81f2-dfa5588c4768', 'Bangunan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('41797880-6724-42f5-81f2-dfa5588c4768', 'たてもの', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('41797880-6724-42f5-81f2-dfa5588c4768', 'すてきなデザインの建物ですね。', 'Ini adalah bangunan yang dirancang dengan sangat bagus, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('41797880-6724-42f5-81f2-dfa5588c4768', '建てられてからまだ一年しかたってないのに、あの建物はもうずい分よごれているね。', 'Baru setahun dibangun, tapi bangunan ini sudah lumayan kotor ya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('41797880-6724-42f5-81f2-dfa5588c4768', '「あなたとその建物を一緒に見に行きたいと思うのですが、いつがご都合よろしいですか？」「ええっと、あなたのご都合に合わせますよ。」', '"Aku ingin pergi melihat gedung itu bersamamu, jadi kapan waktu yang tepat bagimu?" "Yah, aku akan menyesuaikan jadwalku."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('90575f91-5565-4bd7-938f-3d5f93bb426f', 'vocabulary', '建前', '建前', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Apa yang Anda bangun di depan orang lain adalah citra publik Anda. Ini adalah perilaku publik Anda, cara Anda bertindak di sekitar orang lain yang sebenarnya tidak Anda kenal. Konsep ini ternyata sangat penting di Jepang, jadi Anda akan cukup sering mendengarnya meskipun konsep ini aneh di tempat lain. Anda harus memikirkan hal ini seperti Anda sedang membangun bangunan kepribadian di depan Anda. Ini menunjukkan siapa diri Anda di luar, namun melindungi apa yang ada di dalam.', 'Apa yang Anda bangun di depan orang lain adalah citra publik Anda. Ini adalah perilaku publik Anda, cara Anda bertindak di sekitar orang lain yang sebenarnya tidak Anda kenal. Konsep ini ternyata sangat penting di Jepang, jadi Anda akan cukup sering mendengarnya meskipun konsep ini aneh di tempat lain. Anda harus memikirkan hal ini seperti Anda sedang membangun bangunan kepribadian di depan Anda. Ini menunjukkan siapa diri Anda di luar, namun melindungi apa yang ada di dalam.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('90575f91-5565-4bd7-938f-3d5f93bb426f', 'Perilaku Masyarakat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('90575f91-5565-4bd7-938f-3d5f93bb426f', 'Public Behaviour', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('90575f91-5565-4bd7-938f-3d5f93bb426f', 'Official Stance', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('90575f91-5565-4bd7-938f-3d5f93bb426f', 'Public Position', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('90575f91-5565-4bd7-938f-3d5f93bb426f', 'Public Face', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('90575f91-5565-4bd7-938f-3d5f93bb426f', 'Tatemae', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('90575f91-5565-4bd7-938f-3d5f93bb426f', 'たてまえ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('90575f91-5565-4bd7-938f-3d5f93bb426f', 'ビエトは本音と建前を使い分けるのが上手い。', 'Viet pandai memisahkan diri publik dan pribadinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('90575f91-5565-4bd7-938f-3d5f93bb426f', 'しょうかいじょうが無いとここの医者にみてもらえないというのは建前です。', 'Pendirian resmi kami adalah Anda tidak dapat menemui dokter di sini tanpa surat referensi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('90575f91-5565-4bd7-938f-3d5f93bb426f', 'よく「本音と建前」は日本独特の文化だと言われますが、実際は世界中に存在します。', 'Sering dikatakan bahwa "kontras antara perasaan pribadi dan perilaku publik" adalah karakteristik unik budaya Jepang, namun hal ini juga terjadi di seluruh dunia.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5d71d67d-eec4-44d5-a7a9-34a313bebd3b', 'vocabulary', '上品', '上品', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ingat bagaimana 下品 bersifat "kasar" dan "vulgar" - ini jelas merupakan kebalikannya. Ini elegan.', 'Ingat bagaimana 下品 bersifat "kasar" dan "vulgar" - ini jelas merupakan kebalikannya. Ini elegan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5d71d67d-eec4-44d5-a7a9-34a313bebd3b', 'Elegan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5d71d67d-eec4-44d5-a7a9-34a313bebd3b', 'じょうひん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d71d67d-eec4-44d5-a7a9-34a313bebd3b', '母は時々上品な仕草を見せる時があります。', 'Terkadang ibuku menunjukkan tingkah lakunya yang elegan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d71d67d-eec4-44d5-a7a9-34a313bebd3b', '私の友達はミセスコンテストで上品な言葉づかいでスピーチした。', 'Teman saya memberikan pidato dengan bahasa yang elegan di kontes Ny.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d71d67d-eec4-44d5-a7a9-34a313bebd3b', 'カナエはいつも上品にナイフとフォークを使うように両親からキツく言われている。', 'Orang tua Kanae selalu sangat tegas dalam menyuruhnya menggunakan pisau dan garpu dengan elegan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ec8dcbae-ab16-4d98-864f-cfc9f9bb244b', 'vocabulary', '出発', '出発', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Anda keluar dan kemudian berangkat. Ini hanyalah sebuah keberangkatan.', 'Anda keluar dan kemudian berangkat. Ini hanyalah sebuah keberangkatan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ec8dcbae-ab16-4d98-864f-cfc9f9bb244b', 'Keberangkatan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ec8dcbae-ab16-4d98-864f-cfc9f9bb244b', 'しゅっぱつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ec8dcbae-ab16-4d98-864f-cfc9f9bb244b', '出発まで五分です。', 'Ada lima menit lagi sampai keberangkatan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ec8dcbae-ab16-4d98-864f-cfc9f9bb244b', '二週間後に、東京に出発する予定です。', 'Aku akan berangkat ke Tokyo dalam dua minggu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ec8dcbae-ab16-4d98-864f-cfc9f9bb244b', 'ほとんど喋ったことのない同僚の出発の門出を祝う飲み会にお誘い頂き、どうも有難う御座います。', 'Terima kasih banyak telah mengundang saya ke pesta minum untuk merayakan kepergian rekan kerja yang jarang saya ajak bicara.') ON CONFLICT DO NOTHING;
