INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d1277aaa-0fb8-4d90-b21b-4e6287b692f4', '年末ジャンボたからくじはまだ発売中ですか？', 'Apakah Undian Jumbo Akhir Tahun masih dijual?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d1277aaa-0fb8-4d90-b21b-4e6287b692f4', 'これは、トーフグストアで発売中の手ぬぐいです。', 'Ini handuk tenugui yang dijual di toko Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d1277aaa-0fb8-4d90-b21b-4e6287b692f4', '少年ジャンプ６月号、ただ今絶賛発売中。', 'Shonen Jump edisi Juni kini sedang dijual dan mendapat pujian kritis.') ON CONFLICT DO NOTHING;
