INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('44188a82-23b3-42ac-9cec-8a822998d9ff', '思わず本音を口にしてしまいました。', 'Saya berbicara tentang niat saya yang sebenarnya secara tidak sengaja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('44188a82-23b3-42ac-9cec-8a822998d9ff', 'コウイチがすんげー大きな音のオナラをしたから、みんな思わず耳をふさいだんだけど、はなをふさいだ方がよかったね。', 'Koichi kentut begitu keras sehingga semua orang secara refleks menutup telinga, padahal seharusnya kami menutup hidung.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('44188a82-23b3-42ac-9cec-8a822998d9ff', '美味しそうな写真を見て、思わず涎が出た。', 'Saya melihat gambar yang tampak lezat dan tanpa sadar mulai meneteskan air liur.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('12e979f1-b555-4071-a421-3faafd49b878', 'vocabulary', '急', '急', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Maknanya diambil dari bagian kanji yang tiba-tiba, artinya tiba-tiba, mendesak, atau darurat!', 'Maknanya diambil dari bagian kanji yang tiba-tiba, artinya tiba-tiba, mendesak, atau darurat!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
