INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('21f3ef72-3e02-4829-a03b-cdd77fc7caaa', 'たいふう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21f3ef72-3e02-4829-a03b-cdd77fc7caaa', '今回の台風は弱いので、あまり心ぱいしなくてもよさそうです。', 'Topan ini lemah, jadi sepertinya kita tidak perlu terlalu khawatir.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21f3ef72-3e02-4829-a03b-cdd77fc7caaa', 'ひじょうに強い台風トウフ号が、月よう日、西日本に上りくしました。', 'Topan Tofu yang kuat melanda Jepang bagian barat pada hari Senin.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21f3ef72-3e02-4829-a03b-cdd77fc7caaa', '大型の台風が日本列島に近づいています。', 'Topan besar sedang mendekati kepulauan Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4921b141-433e-40b7-9350-95207d06dee7', 'vocabulary', '地中海', '地中海', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Laut tengah bumi adalah Laut Mediterania. Mungkin tidak terlihat seperti berada di tengah bumi, namun dahulu kala itulah yang dipikirkan orang. Ini adalah laut antara Eropa Selatan dan Afrika Utara.', 'Laut tengah bumi adalah Laut Mediterania. Mungkin tidak terlihat seperti berada di tengah bumi, namun dahulu kala itulah yang dipikirkan orang. Ini adalah laut antara Eropa Selatan dan Afrika Utara.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
