INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4921b141-433e-40b7-9350-95207d06dee7', 'さい近、地中海りょうりにハマっているんですよね。', 'Akhir-akhir ini, saya terobsesi dengan masakan Mediterania.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4921b141-433e-40b7-9350-95207d06dee7', 'ただ今、地中海からきたく中でーす。', 'Saya sedang dalam perjalanan pulang dari Laut Mediterania.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4921b141-433e-40b7-9350-95207d06dee7', '夏休みに、家族で地中海をクルーズしてきました。', 'Saya pergi berlayar bersama keluarga saya di Laut Mediterania selama liburan musim panas.') ON CONFLICT DO NOTHING;
